package kz.bekzat.jwt.service;
import kz.bekzat.jwt.dao.UserDao; import kz.bekzat.jwt.model.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class AuthService {private final UserDao users;private final JwtService jwt;private final RefreshTokenService refresh;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();public AuthService(UserDao u,JwtService j,RefreshTokenService r){users=u;jwt=j;refresh=r;}public Map<String,Object> register(String username,String password){if(username==null||username.isBlank()||password==null||password.length()<6)throw new IllegalArgumentException("Username required; password must have 6+ characters");if(users.findByUsername(username).isPresent())throw new IllegalArgumentException("Username already exists");AppUser u=new AppUser(username,encoder.encode(password),Role.USER);users.save(u);return login(username,password);}public Map<String,Object> login(String username,String password){AppUser u=users.findByUsername(username).orElseThrow(()->new IllegalArgumentException("Invalid username or password"));if(!encoder.matches(password,u.getPasswordHash()))throw new IllegalArgumentException("Invalid username or password");return Map.of("accessToken",jwt.createAccessToken(username,u.getRole().name()),"refreshToken",refresh.issue(u.getId()).token(),"tokenType","Bearer","role",u.getRole().name());}}
